    },
    {
      "symbol": "ORLY",
      "direction": "benefit",
      "rationale": "Major aftermarket retailer with heavy exposure to professional installer customers, who benefit from cheaper compliant parts."
    },
    {
      "symbol": "AAP",
      "direction": "benefit",
      "rationale": "Pure-play aftermarket retailer set to gain from reduced regulatory costs and greater parts availability."
    },
    {
      "symbol": "DORM",
      "directive": "benefit",
      "rationale": "Leading supplier of replacement parts; faster certification could unlock new emissions-related product categories."
    },
    {
      "symbol": "LKQ",
